mapper.update:
update tlias.clazz
name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId}, subject = #{subject}, create_time = #{createTime}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select c.id, c.name, c.room, c.begin_date, c.end_date, c.master_id, c.create_time, c.update_time, e.name as master_name, case when curdate() < c.begin_date then '未开班' when curdate() > c.end_date then '已结束' else '在读中' end as status from clazz c left join emp e on c.master_id = e.id
and c.name like concat('%', #{name}, '%')
and c.begin_date >= #{begin}
and c.end_date <= #{end}
order by c.update_time desc
